// Helper: create a simple colored circle with an icon shape
function svgWrap(inner, bg = '#FF6B6B', size = 48) {
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${size} ${size}" width="${size}" height="${size}">${inner}</svg>`;
}

// Generate a data URI from SVG string
function svgToDataUri(svgStr) {
  return `data:image/svg+xml,${encodeURIComponent(svgStr)}`;
}

