// PUBLIC API
// =============================================================

/**
 * Get the SVG data URI for an emoji character.
 * Returns a data:image/svg+xml URI that can be used as <img src>.
 * Falls back to a colorful circle with the emoji text if not mapped.
 */
export function getEmojiIcon(emoji, size = 48) {
  const entry = ICON_SVGS[emoji];
  if (entry) {
    const fullSvg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48" width="${size}" height="${size}">${entry.svg}</svg>`;
    return svgToDataUri(fullSvg);
  }
  
  // Fallback: render emoji as text inside a colored circle
  const fallbackColor = '#' + (Math.abs(emoji.codePointAt(0) * 2654435761) % 0xFFFFFF).toString(16).padStart(6, '0');
  const fallbackSvg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48" width="${size}" height="${size}">
    <circle cx="24" cy="24" r="22" fill="${fallbackColor}" opacity="0.15"/>
    <circle cx="24" cy="24" r="18" fill="${fallbackColor}" opacity="0.25"/>
    <text x="24" y="32" text-anchor="middle" font-size="24">${emoji}</text>
  </svg>`;
  return svgToDataUri(fallbackSvg);
}

/**
 * Get the icon info (name, color) for an emoji.
 */
export function getEmojiInfo(emoji) {
  return ICON_SVGS[emoji] || { name: 'unknown', color: '#9E9E9E' };
}

/**
 * Check if an emoji has a mapped SVG icon.
 */
export function hasEmojiIcon(emoji) {
  return emoji in ICON_SVGS;
}

/**
 * Get all mapped emoji characters.
 */
export function getAllMappedEmojis() {
  return Object.keys(ICON_SVGS);
}

export default ICON_SVGS;
